feed:
	{{ config.title }}
		{%- if term %} - {{ term.name }}
    {%- elif section and section.title %} - {{ section.title }}
		{%- endif -%}

	{%- if config.description %}
	{{ config.description }}
	{%- endif %}


	Zola
	{{ last_updated | date(format="%Y-%m-%dT%H:%M:%S%:z") }}
	{{ feed_url | safe }}
	{%- for page in pages %}

		{{ page.title }}
		{{ page.date | date(format="%Y-%m-%dT%H:%M:%S%:z") }}
		{% if page.updated %}{{ page.updated | date(format="%Y-%m-%dT%H:%M:%S%:z") }}{% else %}{{ page.date | date(format="%Y-%m-%dT%H:%M:%S%:z") }}{% endif %}

		{{ page.permalink | safe }}
		{{ page.content }}

	{%- endfor %}
